pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testRegression_property() public {
        vm.warp(12345);
        vm.roll(67890);
        uint random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
        vm.warp(12345);
        vm.roll(67890);
        if (random == 0) {
            vm.warp(12346);
        }

        address player = address(0x1234);
        vm.deal(player, 10 wei);
        vm.prank(player);
        c.play{value: 10 wei}();

        assertTrue(address(c).balance == 10 wei);
    }
}
